<?php
declare(strict_types=1);$config=require dirname(__DIR__).'/config/app.php';require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Services/Authorization.php';Security::sendSecurityHeaders($config);Security::startSession($config);if(!Security::enforceAuthenticatedSession($config)){Security::destroySession();header('Location: login.php');exit;}try{$db=Database::connection();$user=Authorization::user($db,(int)$_SESSION['user_id']);if(!$user)throw new RuntimeException('Account unavailable.');$q=$db->prepare('SELECT * FROM user_profiles WHERE user_id=:u LIMIT 1');$q->execute(['u'=>$user['user_id']]);$profile=$q->fetch(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){http_response_code(503);exit('Profile unavailable.');}$base=rtrim(dirname($_SERVER['SCRIPT_NAME']),'/\\');if($base==='/')$base='';function profileUrl(string $p=''):string{global $base;return $base.'/'.ltrim($p,'/');}require dirname(__DIR__).'/app/Core/PublicPage.php';pageHeader('My Profile');?><main class="section"><article class="content-panel"><h1>My Profile</h1><p>Account information currently stored in the portal.</p><dl><?php foreach(['username'=>'Username','email'=>'Email','account_type'=>'Account type','account_status'=>'Account status'] as $k=>$label):?><dt><?= Security::e($label) ?></dt><dd><?= Security::e($user[$k]??'') ?></dd><?php endforeach;foreach(['first_name'=>'First name','middle_name'=>'Middle name','last_name'=>'Last name','mobile_number'=>'Mobile number','address_line'=>'Address','barangay'=>'Barangay','municipality'=>'Municipality','province'=>'Province'] as $k=>$label):?><dt><?= Security::e($label) ?></dt><dd><?= Security::e($profile[$k]??'Not provided') ?></dd><?php endforeach;?></dl><a class="action-secondary" href="<?= Security::e(profileUrl('dashboard.php')) ?>">Return to dashboard</a></article></main><?php pageFooter();
